#include <algorithm>

class Solution {
public:
    int trap(vector<int>& height) {

        int n = height.size();
        vector<int> left_max(n);
        vector<int> right_max(n);

        int water_level_sum = 0;

        left_max[0] = height[0];
        right_max[0] = height[n-1];

        for(int i=1; i<n-1; i++) {
            for(int j=0; j<i; j++) {
                left_max[i] = max(height[j], left_max[i]);
            }
            for(int j=i+1; j<n; j++) {
                right_max[i] = max(height[j], right_max[i]);
            }

            int water_level = min(left_max[i], right_max[i]);
            if (water_level > height[i])
                water_level_sum += water_level - height[i];
        }
        return water_level_sum;
    }
};

